keyConcepts.codeExample:
record Order(String customer, int amountCents, boolean paid) {
    Order {
        if (amountCents <= 0) throw new IllegalArgumentException("amountCents");
    }
}

class OrderReportService {
    Report summarize(List<Order> orders) {
        var paid = orders.stream().filter(Order::paid).toList();
        int revenue = paid.stream().mapToInt(Order::amountCents).sum();
        return new Report(paid.size(), revenue); // aucune I/O, aucune règle cachée ailleurs
    }
}

